1	package meter
2	
3	import (
4		"sort"
5		"sync"
6		"time"
7	)
8	
9	// Service 是订阅、用量与账单的本地内存服务。
10	// 单个 *Service 可被多个 goroutine 并发使用：重复提交只会生效一次。
11	type Service struct {
12		mu       sync.Mutex
13		now      func() time.Time
14		accounts map[string]*account
15		plans    map[string]Plan
16	}
17	
18	type subRecord struct {
19		planID      string
20		terms       PlanTerms
21		activatedAt time.Time
22	}
23	
24	type eventRecord struct {
25		at     time.Time
26		qty    int64
27		period Month
28	}
29	
30	type billRecord struct {
31		bill Bill
32	}
33	
34	type paymentRecord struct {
35		period Month
36		amount int64
37	}
38	
39	type account struct {
40		id       string
41		sub      *subRecord
42		events   map[string]eventRecord
43		usage    map[Month]int64
44		bills    map[Month]*billRecord
45		payments map[string]paymentRecord
46	}
47	
48	// NewService 创建一个以系统时钟判断“当前时刻”的服务。
49	func NewService() *Service {
50		return NewServiceWithClock(time.Now)
51	}
52	
53	// NewServiceWithClock 创建使用自定义时钟的服务，便于测试账期与截止时刻。
54	func NewServiceWithClock(now func() time.Time) *Service {
55		if now == nil {
56			now = time.Now
57		}
58		return &Service{
59			now:      now,
60			accounts: make(map[string]*account),
61			plans:    make(map[string]Plan),
62		}
63	}
64	
65	func (s *Service) nowUTC() time.Time {
66		return s.now().UTC()
67	}
68	
69	// CreateAccount 创建业务账户。账户标识必须非空且唯一。
70	func (s *Service) CreateAccount(id string) error {
71		if id == "" {
72			return invalidf("account id is empty")
73		}
74		s.mu.Lock()
75		defer s.mu.Unlock()
76		if _, ok := s.accounts[id]; ok {
77			return ErrAccountExists
78		}
79		s.accounts[id] = &account{
80			id:       id,
81			events:   make(map[string]eventRecord),
82			usage:    make(map[Month]int64),
83			bills:    make(map[Month]*billRecord),
84			payments: make(map[string]paymentRecord),
85		}
86		return nil
87	}
88	
89	func validatePlan(p Plan) error {
90		if p.ID == "" {
91			return invalidf("plan id is empty")
92		}
93		if p.MonthlyFee < 0 || p.IncludedUnits < 0 || p.OveragePrice < 0 {
94			return invalidf("plan %q has negative amount or quantity", p.ID)
95		}
96		if p.TaxRateBasisPoints < 0 || p.TaxRateBasisPoints > 10000 {
97			return invalidf("plan %q tax rate %d out of [0,10000]", p.ID, p.TaxRateBasisPoints)
98		}
99		return nil
100	}
101	
102	// CreatePlan 创建套餐。金额单位为分，税率为万分比且在 [0,10000]。
103	func (s *Service) CreatePlan(p Plan) error {
104		if err := validatePlan(p); err != nil {
105			return err
106		}
107		s.mu.Lock()
108		defer s.mu.Unlock()
109		if _, ok := s.plans[p.ID]; ok {
110			return ErrPlanExists
111		}
112		s.plans[p.ID] = p
113		return nil
114	}
115	
116	// UpdatePlan 更新套餐当前条件。只影响之后开通的订阅，
117	// 已开通订阅继续使用开通时保存的快照。
118	func (s *Service) UpdatePlan(p Plan) error {
119		if err := validatePlan(p); err != nil {
120			return err
121		}
122		s.mu.Lock()
123		defer s.mu.Unlock()
124		if _, ok := s.plans[p.ID]; !ok {
125			return ErrPlanNotFound
126		}
127		s.plans[p.ID] = p
128		return nil
129	}
130	
131	// Subscribe 为账户开通订阅，并保存当时的套餐条件快照。
132	// 每个账户只允许一份有效订阅；从 activatedAt 起接收用量，
133	// 首月仍收完整月费并提供完整额度。
134	func (s *Service) Subscribe(accountID, planID string, activatedAt time.Time) error {
135		if accountID == "" {
136			return invalidf("account id is empty")
137		}
138		if planID == "" {
139			return invalidf("plan id is empty")
140		}
141		if activatedAt.IsZero() {
142			return invalidf("activated at is zero")
143		}
144		s.mu.Lock()
145		defer s.mu.Unlock()
146		acc, ok := s.accounts[accountID]
147		if !ok {
148			return ErrAccountNotFound
149		}
150		plan, ok := s.plans[planID]
151		if !ok {
152			return ErrPlanNotFound
153		}
154		if acc.sub != nil {
155			return ErrSubscriptionExists
156		}
157		acc.sub = &subRecord{
158			planID:      planID,
159			terms:       termsOf(plan),
160			activatedAt: activatedAt.UTC(),
161		}
162		return nil
163	}
164	
165	// RecordEvent 上报一条用量事件。
166	//
167	// 事件按发生时刻归入 UTC 自然月账期；早于订阅开通或晚于当前时刻的事件被拒绝。
168	// 事件标识在同一账户内去重：完全相同的重报返回原结果且不重复累计，
169	// 相同标识但时刻或数量不同返回 ErrEventConflict。
170	// 已出账月份拒绝新事件；账户因到期欠费停用时拒绝新事件；
171	// 但此前已接收事件的完全相同重报始终成功。
172	func (s *Service) RecordEvent(e Event) (EventResult, error) {
173		if e.AccountID == "" {
174			return EventResult{}, invalidf("account id is empty")
175		}
176		if e.EventID == "" {
177			return EventResult{}, invalidf("event id is empty")
178		}
179		if e.Quantity < 0 {
180			return EventResult{}, invalidf("event %q has negative quantity %d", e.EventID, e.Quantity)
181		}
182		if e.At.IsZero() {
183			return EventResult{}, invalidf("event %q has zero timestamp", e.EventID)
184		}
185		at := e.At.UTC()
186	
187		s.mu.Lock()
188		defer s.mu.Unlock()
189	
190		acc, ok := s.accounts[e.AccountID]
191		if !ok {
192			return EventResult{}, ErrAccountNotFound
193		}
194		if acc.sub == nil {
195			return EventResult{}, ErrSubscriptionNotFound
196		}
197	
198		// 去重优先：完全相同的重报即使发生在出账后或停用期间也返回成功。
199		if prev, ok := acc.events[e.EventID]; ok {
200			if !prev.at.Equal(at) || prev.qty != e.Quantity {
201				return EventResult{}, ErrEventConflict
202			}
203			return EventResult{Accepted: false, Period: prev.period}, nil
204		}
205	
206		if at.Before(acc.sub.activatedAt) {
207			return EventResult{}, ErrEventBeforeSubscription
208		}
209		now := s.nowUTC()
210		if at.After(now) {
211			return EventResult{}, ErrEventInFuture
212		}
213	
214		period := MonthOf(at)
215		if _, billed := acc.bills[period]; billed {
216			return EventResult{}, ErrMonthBilled
217		}
218		if s.isSuspendedLocked(acc, now) {
219			return EventResult{}, ErrSuspended
220		}
221	
222		total, ok := addNonNeg(acc.usage[period], e.Quantity)
223		if !ok {
224			return EventResult{}, ErrOverflow
225		}
226		// 所有校验通过后才落库：失败不消耗事件标识。
227		acc.events[e.EventID] = eventRecord{at: at, qty: e.Quantity, period: period}
228		acc.usage[period] = total
229		return EventResult{Accepted: true, Period: period}, nil
230	}
231	
232	// CreateBill 为账户指定账期生成账单（账期不存在则幂等返回同一张）。
233	// 只能为开通当月及以后、且已经结束的月份生成账单。
234	// 重复调用得到同一账单；出账后金额与用量明细固定。
235	func (s *Service) CreateBill(accountID string, period Month) (Bill, error) {
236		if accountID == "" {
237			return Bill{}, invalidf("account id is empty")
238		}
239		if period.Month < time.January || period.Month > time.December {
240			return Bill{}, invalidf("invalid billing period %d-%d", period.Year, period.Month)
241		}
242		s.mu.Lock()
243		defer s.mu.Unlock()
244	
245		acc, ok := s.accounts[accountID]
246		if !ok {
247			return Bill{}, ErrAccountNotFound
248		}
249		if acc.sub == nil {
250			return Bill{}, ErrSubscriptionNotFound
251		}
252		if existing, ok := acc.bills[period]; ok {
253			return existing.bill, nil
254		}
255	
256		activationMonth := MonthOf(acc.sub.activatedAt)
257		if period.Before(activationMonth) {
258			return Bill{}, ErrBillBeforeSubscription
259		}
260		now := s.nowUTC()
261		if !period.End().Before(now) && !period.End().Equal(now) {
262			return Bill{}, ErrBillMonthNotEnded
263		}
264	
265		bill, err := buildBill(accountID, period, acc.sub.terms, acc.usage[period])
266		if err != nil {
267			return Bill{}, err
268		}
269		acc.bills[period] = &billRecord{bill: bill}
270		return bill, nil
271	}
272	
273	// GetBill 返回指定账期的账单；尚未出账返回 ErrBillNotFound。
274	func (s *Service) GetBill(accountID string, period Month) (Bill, error) {
275		if accountID == "" {
276			return Bill{}, invalidf("account id is empty")
277		}
278		s.mu.Lock()
279		defer s.mu.Unlock()
280		acc, ok := s.accounts[accountID]
281		if !ok {
282			return Bill{}, ErrAccountNotFound
283		}
284		rec, ok := acc.bills[period]
285		if !ok {
286			return Bill{}, ErrBillNotFound
287		}
288		return rec.bill, nil
289	}
290	
291	// RecordPayment 为指定账单登记一笔大于零且不超过余额的本地付款，支持分次登记。
292	// 付款标识在同一账户内去重：相同账单和金额的重报返回原结果，
293	// 改成其他账单或金额返回 ErrPaymentConflict；失败不消耗付款标识。
294	func (s *Service) RecordPayment(accountID, paymentID string, period Month, amount int64) (PaymentResult, error) {
295		if accountID == "" {
296			return PaymentResult{}, invalidf("account id is empty")
297		}
298		if paymentID == "" {
299			return PaymentResult{}, invalidf("payment id is empty")
300		}
301		if amount <= 0 {
302			return PaymentResult{}, invalidf("payment %q amount must be positive, got %d", paymentID, amount)
303		}
304		s.mu.Lock()
305		defer s.mu.Unlock()
306	
307		acc, ok := s.accounts[accountID]
308		if !ok {
309			return PaymentResult{}, ErrAccountNotFound
310		}
311		// 去重先于账单查找：相同标识改指向其他账单（哪怕不存在）也是冲突。
312		if prev, ok := acc.payments[paymentID]; ok {
313			if prev.period != period || prev.amount != amount {
314				return PaymentResult{}, ErrPaymentConflict
315			}
316			rec, ok := acc.bills[period]
317			if !ok {
318				return PaymentResult{}, ErrBillNotFound
319			}
320			return PaymentResult{
321				Registered:  false,
322				Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
323				BillBalance: rec.bill.Balance,
324				Settled:     rec.bill.Settled,
325			}, nil
326		}
327	
328		rec, ok := acc.bills[period]
329		if !ok {
330			return PaymentResult{}, ErrBillNotFound
331		}
332	
333		if amount > rec.bill.Balance {
334			return PaymentResult{}, ErrPaymentExceedsBalance
335		}
336	
337		paid, ok := addNonNeg(rec.bill.Paid, amount)
338		if !ok {
339			return PaymentResult{}, ErrOverflow
340		}
341		rec.bill.Paid = paid
342		rec.bill.Balance -= amount
343		if rec.bill.Balance == 0 {
344			rec.bill.Settled = true
345		}
346		acc.payments[paymentID] = paymentRecord{period: period, amount: amount}
347	
348		return PaymentResult{
349			Registered:  true,
350			Payment:     Payment{AccountID: accountID, PaymentID: paymentID, Period: period, Amount: amount},
351			BillBalance: rec.bill.Balance,
352			Settled:     rec.bill.Settled,
353		}, nil
354	}
355	
356	// MonthlyUsage 返回账户某账期的累计用量；无任何用量时返回 0。
357	func (s *Service) MonthlyUsage(accountID string, period Month) (Usage, error) {
358		if accountID == "" {
359			return Usage{}, invalidf("account id is empty")
360		}
361		s.mu.Lock()
362		defer s.mu.Unlock()
363		acc, ok := s.accounts[accountID]
364		if !ok {
365			return Usage{}, ErrAccountNotFound
366		}
367		return Usage{Period: period, Total: acc.usage[period]}, nil
368	}
369	
370	// Status 返回账户状态：各月累计用量、各账单余额以及当前是否因欠费停用。
371	func (s *Service) Status(accountID string) (AccountStatus, error) {
372		if accountID == "" {
373			return AccountStatus{}, invalidf("account id is empty")
374		}
375		s.mu.Lock()
376		defer s.mu.Unlock()
377		acc, ok := s.accounts[accountID]
378		if !ok {
379			return AccountStatus{}, ErrAccountNotFound
380		}
381	
382		periodSet := make(map[Month]struct{}, len(acc.usage)+len(acc.bills))
383		for m := range acc.usage {
384			periodSet[m] = struct{}{}
385		}
386		for m := range acc.bills {
387			periodSet[m] = struct{}{}
388		}
389		periods := make([]Month, 0, len(periodSet))
390		for m := range periodSet {
391			periods = append(periods, m)
392		}
393		sortMonths(periods)
394	
395		st := AccountStatus{
396			AccountID:    accountID,
397			Subscribed:   acc.sub != nil,
398			Suspended:    s.isSuspendedLocked(acc, s.nowUTC()),
399			MonthlyUsage: make([]Usage, 0, len(periods)),
400			Bills:        make([]BillSummary, 0, len(acc.bills)),
401		}
402		for _, m := range periods {
403			st.MonthlyUsage = append(st.MonthlyUsage, Usage{Period: m, Total: acc.usage[m]})
404		}
405		for _, m := range periods {
406			if rec, ok := acc.bills[m]; ok {
407				b := rec.bill
408				st.Bills = append(st.Bills, BillSummary{
409					Period:   m,
410					TotalDue: b.TotalDue,
411					Paid:     b.Paid,
412					Balance:  b.Balance,
413					Settled:  b.Settled,
414					DueAt:    b.DueAt,
415				})
416			}
417		}
418		return st, nil
419	}
420	
421	// isSuspendedLocked 报告账户当前是否停用：
422	// 存在到达付款截止时刻仍有余额的账单。调用时持有 s.mu。
423	func (s *Service) isSuspendedLocked(acc *account, now time.Time) bool {
424		for _, rec := range acc.bills {
425			if !rec.bill.Settled && !now.Before(rec.bill.DueAt) {
426				return true
427			}
428		}
429		return false
430	}
431	
432	func sortMonths(ms []Month) {
433		sort.Slice(ms, func(i, j int) bool { return ms[i].Before(ms[j]) })
434	}
435	
436	// addNonNeg 返回两个非负 int64 之和；溢出时 ok=false。
437	func addNonNeg(a, b int64) (int64, bool) {
438		if a > maxInt64-b {
439			return 0, false
440		}
441		return a + b, true
442	}
443	
444	// mulNonNeg 返回两个非负 int64 之积；溢出时 ok=false。
445	func mulNonNeg(a, b int64) (int64, bool) {
446		if a == 0 || b == 0 {
447			return 0, true
448		}
449		if a > maxInt64/b {
450			return 0, false
451		}
452		return a * b, true
453	}
454	
455	// buildBill 依据套餐快照和账期总用量计算账单，所有金额运算做溢出检查。
456	func buildBill(accountID string, period Month, t PlanTerms, totalUsage int64) (Bill, error) {
457		overageUnits := int64(0)
458		if totalUsage > t.IncludedUnits {
459			overageUnits = totalUsage - t.IncludedUnits
460		}
461		overageFee, ok := mulNonNeg(overageUnits, t.OveragePrice)
462		if !ok {
463			return Bill{}, ErrOverflow
464		}
465		subtotal, ok := addNonNeg(t.MonthlyFee, overageFee)
466		if !ok {
467			return Bill{}, ErrOverflow
468		}
469		tax, ok := rateAmount(subtotal, t.TaxRateBasisPoints)
470		if !ok {
471			return Bill{}, ErrOverflow
472		}
473		totalDue, ok := addNonNeg(subtotal, tax)
474		if !ok {
475			return Bill{}, ErrOverflow
476		}
477		b := Bill{
478			AccountID:     accountID,
479			Period:        period,
480			Terms:         t,
481			TotalUsage:    totalUsage,
482			IncludedUnits: t.IncludedUnits,
483			OverageUnits:  overageUnits,
484			MonthlyFee:    t.MonthlyFee,
485			OverageFee:    overageFee,
486			Tax:           tax,
487			TotalDue:      totalDue,
488			Paid:          0,
489			Balance:       totalDue,
490			Settled:       totalDue == 0,
491			DueAt:         period.End().AddDate(0, 0, 7),
492		}
493		return b, nil
494	}
495	
496	// rateAmount 计算 amount*rate/10000 并四舍五入到分（非负数，半数向上）。
497	// 拆分商和余数计算以避免乘积溢出 int64。
498	func rateAmount(amount, rate int64) (int64, bool) {
499		const den = 10000
500		q, r := amount/den, amount%den
501		qr, ok := mulNonNeg(q, rate)
502		if !ok {
503			return 0, false
504		}
505		rr, ok := mulNonNeg(r, rate)
506		if !ok {
507			return 0, false
508		}
509		// 四舍五入：(rr + den/2) / den，rr < den*10001 < 1e8，加 den/2 不溢出。
510		add, ok := addNonNeg(qr, (rr+den/2)/den)
511		if !ok {
512			return 0, false
513		}
514		return add, true
515	}
