402		if _, err := s.CreateBill("a", jan(2026)); err != nil {
403			t.Fatal(err)
404		}
405	
406		// 截止前正常接收 2 月用量。
407		clk.t = utc(2026, 2, 2, 0, 0)
408		febEvent := Event{AccountID: "a", EventID: "f1", At: utc(2026, 2, 2, 0, 0), Quantity: 1}
409		if _, err := s.RecordEvent(febEvent); err != nil {
410			t.Fatalf("event before due: %v", err)
411		}
412	
413		// 到达截止时刻仍有余额：停用。
414		clk.t = utc(2026, 2, 8, 0, 0)
415		st, _ := s.Status("a")
416		if !st.Suspended {
417			t.Fatalf("should be suspended: %+v", st)
418		}
419		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f2", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
420			t.Fatalf("new event while suspended: %v", err)
421		}
422		// 已接收事件的相同重报仍成功。
423		if r, err := s.RecordEvent(janEvent); err != nil || r.Accepted {
424			t.Fatalf("jan replay suspended: %+v %v", r, err)
425		}
426		if r, err := s.RecordEvent(febEvent); err != nil || r.Accepted {
427			t.Fatalf("feb replay suspended: %+v %v", r, err)
428		}
429	
430		// 部分付款仍欠费，继续停用。
431		if _, err := s.RecordPayment("a", "p1", jan(2026), 500); err != nil {
432			t.Fatal(err)
433		}
434		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f3", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); !errors.Is(err, ErrSuspended) {
435			t.Fatalf("still suspended after partial pay: %v", err)
436		}
437	
438		// 结清后立即恢复；2 月账单尚未生成，新用量可继续累计。
439		if _, err := s.RecordPayment("a", "p2", jan(2026), 500); err != nil {
440			t.Fatal(err)
441		}
442		st, _ = s.Status("a")
443		if st.Suspended {
444			t.Fatalf("should resume: %+v", st)
445		}
446		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "f3", At: utc(2026, 2, 3, 0, 0), Quantity: 1}); err != nil {
447			t.Fatalf("event after resume: %v", err)
448		}
449		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != 2 {
450			t.Fatalf("feb usage = %d want 2", u.Total)
451		}
452	
453		// Status 中应能看到各月用量与账单余额。
454		if len(st.MonthlyUsage) != 2 || st.MonthlyUsage[0].Period != jan(2026) || st.MonthlyUsage[1].Period != feb(2026) {
455			t.Fatalf("monthly usage: %+v", st.MonthlyUsage)
456		}
457		if len(st.Bills) != 1 || st.Bills[0].Period != jan(2026) || st.Bills[0].Balance != 0 || !st.Bills[0].Settled {
458			t.Fatalf("bills: %+v", st.Bills)
459		}
460	}
461	
462	func TestOverflowLeavesNoTrace(t *testing.T) {
463		s, clk := newTestService(utc(2026, 2, 1, 0, 0))
464		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 1, TaxRateBasisPoints: 0})
465		mustAccount(t, s, "a")
466		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
467			t.Fatal(err)
468		}
469	
470		base := maxInt64 - 5
471		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "base", At: utc(2026, 1, 10, 0, 0), Quantity: base}); err != nil {
472			t.Fatal(err)
473		}
474		// 本次累计将溢出：失败且不消耗事件标识。
475		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "try", At: utc(2026, 1, 11, 0, 0), Quantity: 6}); !errors.Is(err, ErrOverflow) {
476			t.Fatalf("usage overflow: %v", err)
477		}
478		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != base {
479			t.Fatalf("usage after overflow = %d", u.Total)
480		}
481		// 同一标识以不溢出的数量重试，应当成功。
482		if _, err := s.RecordEvent(Event{AccountID: "a", EventID: "try", At: utc(2026, 1, 11, 0, 0), Quantity: 5}); err != nil {
483			t.Fatalf("id reused after overflow failure: %v", err)
484		}
485	
486		// 超额费用溢出：超额用量 maxInt64 * 单价 2。
487		mustAccount(t, s, "b")
488		mustPlan(t, s, Plan{ID: "p2", MonthlyFee: 0, IncludedUnits: 0, OveragePrice: 2, TaxRateBasisPoints: 0})
489		if err := s.Subscribe("b", "p2", utc(2026, 1, 1, 0, 0)); err != nil {
490			t.Fatal(err)
491		}
492		if _, err := s.RecordEvent(Event{AccountID: "b", EventID: "big", At: utc(2026, 1, 10, 0, 0), Quantity: maxInt64}); err != nil {
493			t.Fatal(err)
494		}
495		if _, err := s.CreateBill("b", jan(2026)); !errors.Is(err, ErrOverflow) {
496			t.Fatalf("overage overflow: %v", err)
497		}
498		if _, err := s.GetBill("b", jan(2026)); !errors.Is(err, ErrBillNotFound) {
499			t.Fatalf("partial bill left behind: %v", err)
500		}
501	
502		// 税额与月费之和溢出（月费 maxInt64，税率 100%）。
503		mustAccount(t, s, "c")
504		mustPlan(t, s, Plan{ID: "p3", MonthlyFee: maxInt64, IncludedUnits: 0, OveragePrice: 0, TaxRateBasisPoints: 10000})
505		if err := s.Subscribe("c", "p3", utc(2026, 1, 1, 0, 0)); err != nil {
506			t.Fatal(err)
507		}
508		if _, err := s.CreateBill("c", jan(2026)); !errors.Is(err, ErrOverflow) {
509			t.Fatalf("total overflow: %v", err)
510		}
511	
512		_ = clk
513	}
514	
515	func TestConcurrentDuplicates(t *testing.T) {
516		s, clk := newTestService(utc(2026, 2, 1, 0, 0))
517		mustPlan(t, s, Plan{ID: "p", MonthlyFee: 1000, IncludedUnits: 5, OveragePrice: 10, TaxRateBasisPoints: 1000})
518		mustAccount(t, s, "a")
519		if err := s.Subscribe("a", "p", utc(2026, 1, 1, 0, 0)); err != nil {
520			t.Fatal(err)
521		}
522		ev := Event{AccountID: "a", EventID: "dup", At: utc(2026, 1, 10, 0, 0), Quantity: 7}
523	
524		const n = 64
525		var wg sync.WaitGroup
526		var accepted int64
527		var mu sync.Mutex
528		wg.Add(n)
529		for i := 0; i < n; i++ {
530			go func() {
531				defer wg.Done()
532				r, err := s.RecordEvent(ev)
533				if err != nil {
534					t.Errorf("concurrent event: %v", err)
535					return
536				}
537				if r.Accepted {
538					mu.Lock()
539					accepted++
540					mu.Unlock()
541				}
542			}()
543		}
544		wg.Wait()
545		if accepted != 1 {
546			t.Fatalf("accepted = %d, want 1", accepted)
547		}
548		if u, _ := s.MonthlyUsage("a", jan(2026)); u.Total != 7 {
549			t.Fatalf("usage = %d, want 7", u.Total)
550		}
551	
552		// 并发出账只生成一张。
553		bills := make([]Bill, n)
554		wg.Add(n)
555		for i := 0; i < n; i++ {
556			go func(i int) {
557				defer wg.Done()
558				b, err := s.CreateBill("a", jan(2026))
559				if err != nil {
560					t.Errorf("concurrent bill: %v", err)
561					return
562				}
563				bills[i] = b
564			}(i)
565		}
566		wg.Wait()
567		var due int64 = -1
568		for _, b := range bills {
569			if due == -1 {
570				due = b.TotalDue
571			} else if b.TotalDue != due {
572				t.Fatalf("bills differ: %d vs %d", due, b.TotalDue)
573			}
574		}
575		// fee 1000 + overage (7-5)*10=20 => subtotal 1020, tax 102 => 1122
576		if due != 1122 {
577			t.Fatalf("due = %d, want 1122", due)
578		}
579	
580		// 并发同标识付款只扣一次。
581		var registered int64
582		wg.Add(n)
583		for i := 0; i < n; i++ {
584			go func() {
585				defer wg.Done()
586				r, err := s.RecordPayment("a", "pay", jan(2026), 1122)
587				if err != nil {
588					t.Errorf("concurrent pay: %v", err)
589					return
590				}
591				if r.Registered {
592					mu.Lock()
593					registered++
594					mu.Unlock()
595				}
596			}()
597		}
598		wg.Wait()
599		if registered != 1 {
600			t.Fatalf("registered = %d, want 1", registered)
601		}
602		b, _ := s.GetBill("a", jan(2026))
603		if b.Paid != 1122 || b.Balance != 0 || !b.Settled {
604			t.Fatalf("bill after concurrent pay: paid=%d bal=%d settled=%v", b.Paid, b.Balance, b.Settled)
605		}
606	
607		// 并发不同标识事件全部累计一次。
608		wg.Add(n)
609		for i := 0; i < n; i++ {
610			go func(i int) {
611				defer wg.Done()
612				_, err := s.RecordEvent(Event{
613					AccountID: "a",
614					EventID:   fmt.Sprintf("e%d", i),
615					At:        utc(2026, 2, 1, 0, 0),
616					Quantity:  1,
617				})
618				if err != nil {
619					t.Errorf("distinct event: %v", err)
620				}
621			}(i)
622		}
623		wg.Wait()
624		if u, _ := s.MonthlyUsage("a", feb(2026)); u.Total != n {
625			t.Fatalf("feb usage = %d, want %d", u.Total, n)
626		}
627	
628		_ = clk
629	}
